INSERT INTO `t_painpoint_config_v0` (`subject`, `subject_name`, `level`, `painpoint`)
VALUES
(1, '信息获取', 1, '<strong>信息过载症</strong>：每天摄入300条信息，真正消化的不足3%→你的大脑正在遭受垃圾信息轰炸。痛点消失L2。<br><strong>信息筛选无能</strong>：面对海量信息像在迷宫中打转；文档搜索超15分钟无结果。痛点消失L2。'),
(1, '信息获取', 2, '<strong>认知偏食危机</strong>：只刷感兴趣内容 → 思维萎缩成单向度怪物；行业报告混杂32%谣言。痛点消失L3。<br><strong>信息幻觉症</strong>：收藏100+文章但阅读率<15%；形成"僵尸资源"库。痛点消失L3。<br><strong>信息广度萎缩</strong>：拒绝尝试新领域→被困夕阳行业存款缩水（转型成功者收入+217%，数据来自麦肯锡行业报告（2023））。痛点消失L3。'),
(1, '信息获取', 3, '<strong>信息渠道枯竭</strong>：客户数据库更新脱节市场；信息孤岛率67%。痛点消失L4。<br><strong>信息鉴别失败</strong>：预警滞后，响应延迟；视野盲区率55%；信息更新频率与市场变化速度脱节。"竞聘时误把过时行业报告当论据→信息更新滞后让你在终面被年轻人逆袭（薪资差额达¥15W/年）"。痛点消失L4：IPS-前额叶联合激活↑42%，隐性知识捕获率>51%。'),
(2, '分析处理', 1, '<strong>思维骨质疏松</strong>：遇到问题就搜索 → 独立思考肌肉退化；按模板填报表，新增栏目就卡壳。痛点消失L2。'),
(2, '分析处理', 2, '<strong>分析深度不足</strong>：汇报只陈述表面数据 → 35岁遭遇裁员危机；仅能处理显性信息链。痛点消失L3：构建多变量动态模型（R²>0.6）<br><strong>逻辑糖尿病</strong>：碎片化阅读导致思维胰岛素抵抗 → 难深度处理复杂问题。痛点消失L3：前额叶-顶叶功能连接>0.6，支持系统推演。<br><strong>认知代谢阻滞</strong>：收藏100个健身视频≠拥有好身体（收藏≠已掌握）→知识积压未转化，知识库90%都是从未启封的''僵尸资源''（信息幻觉症变体）。痛点消失L3。'),
(2, '分析处理', 3, '<strong>认知滤镜效应</strong>：只接受符合三观信息 → 活于信息茧房；总结规律但未关联发展阶段需求，进行适应性变化。痛点消失L4：ACC-DLPFC协同激活，处理矛盾约束。<br><strong>模式代际复刻：当孩子问"为什么"时回答"记住就行"→培养不会思考的下一代（逻辑思维衰减率45%，引自剑桥儿童发展追踪（2024））。 痛点消失L4：ACC-DLPFC协同激活，打破思维遗传链。<br><strong>分析模式遗传：育儿知识库分类清晰但未更新；用5年前经验应对新挑战。痛点消失L4：树突棘密度+42%（验证于《Journal of Neuroscience》vol.44(3) ），支持方法论迭代升级。'),
(3, '决策选择', 2, '<strong>选择瘫痪症</strong>：中午吃什么纠结半天→决策力杀死机遇；相亲时纠结表白半年沦为备胎（相亲犹豫超3周成功率跌至23%（婚恋平台数据））；重大决策时，总在"好像可以"和"万一错了"之间反复纠结。痛点消失L3。<br><strong>从众决策陷阱：跟风买基金亏损40%；竞聘用过期报告。痛点消失L3。<br><strong>决策框架缺失：凭感觉买基金→亏损率21%；相亲选火锅忽略对方需求。痛点消失L3：基底神经节形成决策模板（多巴胺+25%）'),
(3, '决策选择', 3, '<strong>安全区成瘾</strong>：总是选最保险选项→人生平庸化；投资只选保本理财。<br><strong>决策时间贴现</strong>：忽略长期代价（第4次约会失败，即时满足选择致约会失败率+62%（行为学研究））。痛点消失L4：海马体重构历史路径（虚拟历史路径训练矫正），强化长期结果模拟。'),
(4, '行动执行', 1, '<strong>启动阻力黑洞</strong>：明明知道该做什么，就是无法开始→每个拖延都在喂养焦虑怪兽。痛点消失L2：固化3+高效流程。'),
(4, '行动执行', 2, '<strong>脑体分离症</strong>：想法很丰满，行动很骨感→你的执行力配不上你的认知。痛点消失L3：DLPFC-基底节功能连接+28%，支持计划突变响应。<br><strong>执行脱节症</strong>：计划被意外打乱节奏；会议断网无法继续。痛点消失L3。'),
(4, '行动执行', 3, '<strong>意外溃堤效应</strong>：一些突发事情导致工作停滞。 痛点消失L4。'),
(4, '行动执行', 4, '<strong>执行能效衰减</strong>：应变消耗过多认知资源→核心任务质量下降（如切换方案后工作出错率+35%（企业效能报告））。 痛点消失L5：神经同步训练优化，θ-γ耦合同步性+60%，实现多任务无损协同。'),
(5, '复盘感知', 1, '<strong>认知失忆症</strong>：在同一个坑里跌倒三次→复盘能力不如金鱼（记忆7秒）；投资重复犯错。痛点消失L2。'),
(5, '复盘感知', 2, '<strong>复盘能力残疾</strong>：仅能复述会议基础内容→忽略关键细节；项目总结流于形式。痛点消失L3。<br><strong>代际错误复刻</strong>：当孩子问"为什么"回答"记住就行"→培养不会思考的下一代（亲子教育痛点深化）；逻辑思维代际衰减率45%（剑桥儿童追踪2024）。痛点消失L3。<br><strong>归因表面化</strong>：分析迟到归因闹钟故障（表象）→忽略睡前刷手机（根本）。痛点消失L3：DLPFC-IPS功能连接+50%，定位深层症结。'),
(5, '复盘感知', 3, '<strong>知识僵尸化</strong>：收藏100个健身视频≠拥有好身体→知识积压未转化（信息幻觉症变体）；收藏知识转化率＜15%（哈佛学习科学2023）。痛点消失L4。<br><strong>预测短视症</strong>：供应链风险识别滞后，让事情依然发生；预判出游拥堵但未调整行程→仍被困景区。痛点消失L4：海马-皮层γ波耦合＞0.7，提升长期预判精度。'),
(5, '复盘感知', 4, '<strong>策略冻结效应</strong>：推演多种可能但未升级方法论→沿用原有方式方法（遇到安全事故，仅做安全意识教育）。痛点消失L5：知识转化率从15%→85%（数据依据：企业决策失误率-42%（HBR 2023））.<br><strong>元认知盲区</strong>：复盘事件但未检验方法有效性→持续使用低效工具（比如只考虑人的问题，不优化制度方法，让问题频繁发生）。痛点消失L5：双环复盘术监控复盘过程本身。<br><strong>时间折叠失效</strong>：预测模型运行超过决策窗口错过机会（量化交易报告2023）；构建未来模型未压缩时间维度→预测耗时＞决策窗口。痛点消失L5：神经振荡同步性×2.3，实现实时策略优化。');